import { AsyncLocalStorage } from 'node:async_hooks';
const als = new AsyncLocalStorage<string>();
function rec(tag: string): void { console.log(tag + '=' + String(als.getStore())); }
function sleep(ms: number): Promise<number> { return new Promise<number>((r: (v: number) => void): void => { setTimeout((): void => { r(ms); }, ms); }); }
async function main(): Promise<void> {
  const first = als.run('P1', async (): Promise<number> => { await sleep(1); rec('p1'); return 1; });
  const second = als.run('P2', async (): Promise<number> => { const v = await first; rec('p2-after-p1'); return v + 1; });
  const results = await Promise.all([first, second]);
  console.log('results ' + results.join(','));
  const outer = sleep(1);
  await als.run('C', async (): Promise<void> => { await outer.then((): void => { rec('then-on-outer'); }); });
  als.enterWith('E');
  await sleep(1);
  console.log('enterWith=' + String(als.getStore()));
}
